import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define TD 8
#define TH 4
#define TW 4
#define CIN_CHUNK 8
__device__ __forceinline__ int floordiv_pos(int a, int b) {
    int q = a / b;
    int r = a % b;
    if (r != 0 && r < 0) q -= 1;
    return q;
}
__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int K,
    int stride, int padding, int output_padding, int dilation,
    int groups,
    int C_in_per_group, int C_out_per_group,
    bool has_bias,
    int tiles_d, int tiles_h, int tiles_w,
    int ID, int IH, int IW)
{
    extern __shared__ float smem[];
    int chunk_cap = C_in_per_group < CIN_CHUNK ? C_in_per_group : CIN_CHUNK;
    int weight_chunk_cap = chunk_cap * K * K * K;
    float* s_weight = smem;
    float* s_input = smem + weight_chunk_cap;
    // Each block handles one (n, group) pair and one output spatial tile.
    // The input-channel dimension is processed in bounded-size chunks so that
    // shared memory usage does not grow unboundedly with C_in_per_group.
    int ng = blockIdx.y;
    int group_id = ng % groups;
    int n = ng / groups;
    long tile_id = blockIdx.x;
    int tw_idx = (int)(tile_id % tiles_w);
    long tmp = tile_id / tiles_w;
    int th_idx = (int)(tmp % tiles_h);
    int td_idx = (int)(tmp / tiles_h);
    int d0 = td_idx * TD;
    int h0 = th_idx * TH;
    int w0 = tw_idx * TW;
    int id_lo = floordiv_pos(d0 + padding - (K - 1) * dilation, stride);
    int ih_lo = floordiv_pos(h0 + padding - (K - 1) * dilation, stride);
    int iw_lo = floordiv_pos(w0 + padding - (K - 1) * dilation, stride);
    int local_idx = threadIdx.x;
    int lw = local_idx % TW;
    int tmp2 = local_idx / TW;
    int lh = tmp2 % TH;
    int ld = tmp2 / TH;
    int d_out = d0 + ld;
    int h_out = h0 + lh;
    int w_out = w0 + lw;
    bool valid_out = (d_out < D_out && h_out < H_out && w_out < W_out);
    for (int c_out_in_group = 0; c_out_in_group < C_out_per_group; ++c_out_in_group) {
        int c_out = group_id * C_out_per_group + c_out_in_group;
        float sum = 0.0f;
        for (int c_in_chunk_start = 0; c_in_chunk_start < C_in_per_group; c_in_chunk_start += CIN_CHUNK) {
            int cur_chunk = C_in_per_group - c_in_chunk_start;
            if (cur_chunk > CIN_CHUNK) cur_chunk = CIN_CHUNK;
            // Cooperatively load the input halo for this channel chunk into shared memory.
            int input_chunk_size = cur_chunk * ID * IH * IW;
            for (int i = threadIdx.x; i < input_chunk_size; i += blockDim.x) {
                int c_in_g_local = i / (ID * IH * IW);
                int rem = i % (ID * IH * IW);
                int di = rem / (IH * IW);
                rem = rem % (IH * IW);
                int hi = rem / IW;
                int wi = rem % IW;
                int c_in_g = c_in_chunk_start + c_in_g_local;
                int d_in = id_lo + di;
                int h_in = ih_lo + hi;
                int w_in = iw_lo + wi;
                float val = 0.0f;
                if (d_in >= 0 && d_in < D_in && h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                    int c_in = group_id * C_in_per_group + c_in_g;
                    long input_idx = (((long)n * C_in + c_in) * D_in + d_in) * H_in * W_in + h_in * W_in + w_in;
                    val = input[input_idx];
                }
                s_input[i] = val;
            }
            // Cooperatively load the weight slice for this output channel and channel chunk.
            int weight_chunk_size = cur_chunk * K * K * K;
            for (int i = threadIdx.x; i < weight_chunk_size; i += blockDim.x) {
                int c_in_g_local = i / (K * K * K);
                int rem = i % (K * K * K);
                int kd = rem / (K * K);
                rem = rem % (K * K);
                int kh = rem / K;
                int kw = rem % K;
                int c_in_g = c_in_chunk_start + c_in_g_local;
                int c_in = group_id * C_in_per_group + c_in_g;
                long weight_idx = (((long)c_in * C_out_per_group + c_out_in_group) * K + kd) * K * K + kh * K + kw;
                s_weight[i] = weight[weight_idx];
            }
            __syncthreads();
            if (valid_out) {
                for (int c_in_g_local = 0; c_in_g_local < cur_chunk; ++c_in_g_local) {
                    for (int kd = 0; kd < K; ++kd) {
                        int d_in_nom = d_out + padding - kd * dilation;
                        if (d_in_nom < 0) continue;
                        if (d_in_nom % stride != 0) continue;
                        int d_in = d_in_nom / stride;
                        if (d_in < 0 || d_in >= D_in) continue;
                        int di_local = d_in - id_lo;
                        if (di_local < 0 || di_local >= ID) continue;
                        for (int kh = 0; kh < K; ++kh) {
                            int h_in_nom = h_out + padding - kh * dilation;
                            if (h_in_nom < 0) continue;
                            if (h_in_nom % stride != 0) continue;
                            int h_in = h_in_nom / stride;
                            if (h_in < 0 || h_in >= H_in) continue;
                            int hi_local = h_in - ih_lo;
                            if (hi_local < 0 || hi_local >= IH) continue;
                            for (int kw = 0; kw < K; ++kw) {
                                int w_in_nom = w_out + padding - kw * dilation;
                                if (w_in_nom < 0) continue;
                                if (w_in_nom % stride != 0) continue;
                                int w_in = w_in_nom / stride;
                                if (w_in < 0 || w_in >= W_in) continue;
                                int wi_local = w_in - iw_lo;
                                if (wi_local < 0 || wi_local >= IW) continue;
                                int s_input_idx = ((c_in_g_local * ID + di_local) * IH + hi_local) * IW + wi_local;
                                int s_weight_idx = ((c_in_g_local * K + kd) * K + kh) * K + kw;
                                sum += s_input[s_input_idx] * s_weight[s_weight_idx];
                            }
                        }
                    }
                }
            }
            __syncthreads();
        }
        if (valid_out) {
            if (has_bias) {
                sum += bias[c_out];
            }
            long output_idx = (((long)n * C_out + c_out) * D_out + d_out) * H_out * W_out + h_out * W_out + w_out;
            output[output_idx] = sum;
        }
    }
}
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride, int padding, int output_padding, int dilation, int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);
    int K = weight.size(2);
    int C_out_per_group = weight.size(1);
    int C_out = C_out_per_group * groups;
    int C_in_per_group = C_in / groups;
    int D_out = (D_in - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int H_out = (H_in - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int W_out = (W_in - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());
    int tiles_d = (D_out + TD - 1) / TD;
    int tiles_h = (H_out + TH - 1) / TH;
    int tiles_w = (W_out + TW - 1) / TW;
    long total_tiles = (long)tiles_d * tiles_h * tiles_w;
    int ID = (TD - 1 + (K - 1) * dilation + stride - 1) / stride + 2;
    int IH = (TH - 1 + (K - 1) * dilation + stride - 1) / stride + 2;
    int IW = (TW - 1 + (K - 1) * dilation + stride - 1) / stride + 2;
    int chunk_cap = C_in_per_group < CIN_CHUNK ? C_in_per_group : CIN_CHUNK;
    int weight_chunk_size = chunk_cap * K * K * K;
    long input_chunk_size = (long)chunk_cap * ID * IH * IW;
    size_t shared_mem_size = (size_t)(weight_chunk_size + input_chunk_size) * sizeof(float);
    dim3 grid((unsigned int)total_tiles, (unsigned int)(N * groups));
    dim3 block(TD * TH * TW);
    const float* bias_ptr = nullptr;
    if (has_bias) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }
    if (shared_mem_size > 48 * 1024) {
        cudaError_t attrErr = cudaFuncSetAttribute(conv_transpose3d_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shared_mem_size);
        TORCH_CHECK(attrErr == cudaSuccess, "cudaFuncSetAttribute failed: ", cudaGetErrorString(attrErr));
    }
    conv_transpose3d_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        K,
        stride, padding, output_padding, dilation,
        groups,
        C_in_per_group, C_out_per_group,
        has_bias,
        tiles_d, tiles_h, tiles_w,
        ID, IH, IW
    );
    cudaError_t err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));
    return output;
}
"""

conv_transpose3d_cpp_source = r"""
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride, int padding, int output_padding, int dilation, int groups,
    bool has_bias);
"""

conv_transpose3d_module = load_inline(
    name="conv_transpose3d_module",
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=["conv_transpose3d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0,
                 output_padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

        # weight shape as in nn.ConvTranspose3d: (in_channels, out_channels/groups, k, k, k)
        self.weight = nn.Parameter(torch.empty(in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
            fan_in = in_channels * kernel_size * kernel_size * kernel_size // groups
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()
        if self.has_bias:
            bias = self.bias.contiguous().cuda()
        else:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)

        return conv_transpose3d_module.conv_transpose3d_cuda(
            x, weight, bias,
            self.stride, self.padding, self.output_padding, self.dilation, self.groups,
            self.has_bias
        )


batch_size = 8
in_channels = 48
out_channels = 24
kernel_size = 3
depth = 96
height = 96
width = 96


def get_inputs():
    x = torch.rand(batch_size, in_channels, depth, height, width)
    return [x]


def get_init_inputs():
    return [in_channels, out_channels, kernel_size]

